namespace RemoteControlLAN.Gateway.Models;

public sealed class AppUser { public Guid Id { get; set; } = Guid.NewGuid(); public string Username { get; set; } = string.Empty; public string PasswordHash { get; set; } = string.Empty; public bool IsAdmin { get; set; } = false; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public int FailedLoginCount { get; set; } public DateTime? LockedUntil { get; set; } }
public sealed class AgentRecord { public Guid Id { get; set; } public string AgentName { get; set; } = string.Empty; public string Platform { get; set; } = string.Empty; public string AgentSecretKeyHash { get; set; } = string.Empty; public string? PairingPinHash { get; set; } public DateTime? PairingPinExpiresAt { get; set; } public string? LastSeenIp { get; set; } public DateTime? LastOnlineAt { get; set; } }
public sealed class RemoteSession { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public Guid AgentId { get; set; } public DateTime StartedAt { get; set; } = DateTime.UtcNow; public DateTime? EndedAt { get; set; } public string Status { get; set; } = "Active"; }
public sealed class AuditLog { public long Id { get; set; } public Guid? SessionId { get; set; } public Guid? UserId { get; set; } public Guid? AgentId { get; set; } public string Action { get; set; } = string.Empty; public string? Payload { get; set; } public DateTime Timestamp { get; set; } = DateTime.UtcNow; public string Result { get; set; } = string.Empty; }
